#if defined SHADERLOD_BSL_PRIMARY_CLOUD_CONTEXT && SHADERLOD_REFINEMENT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY && !defined ADVANCED_MATERIALS
