	float xzNormalizeFactor = 10.0 / max(abs(float(CLOUD_HEIGHT) - 72.0), 56.0);
#if SHADERLOD_REFINEMENT_ADAPTER == 1 && defined SHADERLOD_BSL_REFLECTED_CONTEXT && defined OVERWORLD && defined FSH && defined ADVANCED_MATERIALS && defined REFLECTION_SPECULAR && defined REFLECTION_ROUGH && !defined REFLECTION_PREVIOUS && ALPHA_BLEND == 0 && CLOUDS == 2 && CLOUD_BASE == 0 && !defined DISTANT_HORIZONS && !defined VOXY && !defined WORLD_CURVATURE
