	for (int i = 0; i < 16; i++) {
		float traceStep = exp2((i + dither) * 0.5 - 2.0);
		vec3 tracePos = viewPos + lightVec * traceStep;

		vec4 pos = projection * vec4(tracePos, 1.0);
		pos = pos / pos.w * 0.5 + 0.5;

