		shadow *= 1.0 - smoothstep(0.0, 0.5, zDelta) * smoothstep(thickness + 1.0, thickness, zDelta);
		thickness += 0.5;
	}

	vec3 shadowCol = ambientCol / mix(ambientCol, lightCol, shadowMask);

	return mix(shadowCol, vec3(1.0), shadow);
	#else
	return vec3(1.0);
	#endif
}
