bool shaderlodBslCloudWholeOutside(vec3 firstPos, vec3 sampleStep, vec3 cameraPos,
                                  int samples, float fadeEnd, float factor) {
    if (samples < 1 || samples > 33 || !shaderlodBslCloudFinite3(firstPos) ||
        !shaderlodBslCloudFinite3(sampleStep) || !shaderlodBslCloudFinite3(cameraPos) ||
        !(fadeEnd > 0.0 && fadeEnd < 1.0e6) || !(factor > 0.0 && factor < 1.0)) return false;
    // Inspect the SAME actual dithered first position and additive native trajectory.
    // This small geometry prepass has no density/noisetex reads. No analytic FP certificate.
    vec3 probe=firstPos;
    float boundaryMargin=max(0.001,fadeEnd*0.0001);
    for (int j=0; j<samples; ++j) {
        if (!shaderlodBslCloudFinite3(probe)) return false;
        vec2 radial=probe.xz-cameraPos.xz;
        float radius=length(radial);
        float outward=dot(radial,sampleStep.xz);
        float outwardMargin=0.0001*max(1.0,radius*length(sampleStep.xz));
        if (!(radius*factor > fadeEnd+boundaryMargin) || !(outward > outwardMargin)) return false;
        probe += sampleStep;
    }
    return true;
}
