}

float CloudSample(vec2 coord, vec2 wind, float cloudGradient, float sunCoverage, float dither) {
	coord *= 0.004 * CLOUD_STRETCH;

	#if CLOUD_BASE == 0
	vec2 baseCoord = coord * 0.25 + wind;
	vec2 detailCoord = coord.xy * 0.5 - wind * 2.0;

	float noiseBase = CloudSampleBasePerlin(baseCoord);
	float noiseDetail = CloudSampleDetail(detailCoord, cloudGradient);
	float noiseCoverage = CloudCoverageDefault(cloudGradient);

	float noise = CloudCombineDefault(noiseBase, noiseDetail, noiseCoverage, sunCoverage);
	
	return noise;
	#elif CLOUD_BASE == 1
	vec2 baseCoord = coord * 0.5 + wind * 2.0;
	vec2 detailCoord = coord.xy * 0.5 - wind * 2.0;

	float noiseBase = CloudSampleBaseWorley(baseCoord);
	float noiseDetail = CloudSampleDetail(detailCoord, cloudGradient);
	float noiseCoverage = CloudCoverageDefault(cloudGradient);

	float noise = CloudCombineDefault(noiseBase, noiseDetail, noiseCoverage, sunCoverage);
	
	return noise;
	#else
	vec2 baseCoord = coord * 0.15625 + wind * 0.5;

	float noiseBase = CloudSampleBaseBlocky(baseCoord);
	float noiseCoverage = CloudCoverageBlocky(cloudGradient);

	float noise = CloudCombineBlocky(noiseBase, noiseCoverage);

	return noise;
	#endif
}

#if (defined(SHADERLOD_BSL_PRIMARY_CLOUD_CONTEXT) || defined(SHADERLOD_BSL_REFLECTED_CONTEXT)) && defined OVERWORLD && defined FSH && CLOUDS > 0 && CLOUDS < 3 && CLOUD_BASE == 0 && SHADERLOD_REFINEMENT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY
// Same two blue-channel detail lookups and height interpolation at explicit LOD0.
// The pinned native 512x512 noise PNG and runtime sampler level/filter parity remain admission gates.
float ShaderLodCloudDetailLod0(vec2 coord, float cloudGradient) {
    float detailZ = floor(cloudGradient * float(CLOUD_THICKNESS)) * 0.04;
    float detailFrac = fract(cloudGradient * float(CLOUD_THICKNESS));
    float noiseDetailLow = texture2DLod(noisetex, coord.xy + detailZ, 0.0).b;
    float noiseDetailHigh = texture2DLod(noisetex, coord.xy + detailZ + 0.04, 0.0).b;
    return mix(noiseDetailLow, noiseDetailHigh, detailFrac);
}
float ShaderLodCloudPrimaryClearBound(vec2 coord, vec2 wind, float cloudGradient, float sunCoverage, float dither, bool secondary) {
#ifdef ADVANCED_MATERIALS
    if (!secondary) return CloudSample(coord, wind, cloudGradient, sunCoverage, dither);
#endif
    if (!shaderlod_optimization_enabled(secondary ? shaderlodOptReflectionCloudDetail : shaderlodOptCloudPrimaryDetail) || shaderlodPreset != 0 || rainStrength != 0.0)
        return CloudSample(coord, wind, cloudGradient, sunCoverage, dither);
    vec2 nativeCoord = coord;
    coord *= 0.004 * CLOUD_STRETCH;
    vec2 baseCoord = coord * 0.25 + wind;
    vec2 detailCoord = coord.xy * 0.5 - wind * 2.0;
    float noiseBase = CloudSampleBasePerlin(baseCoord);
    float noiseCoverage = CloudCoverageDefault(cloudGradient);
    float detailWeight = 0.0476 * CLOUD_DETAIL;
    if (!(noiseBase >= 0.0 && noiseBase <= 1.0 && cloudGradient >= 0.0 && cloudGradient <= 1.0 &&
          sunCoverage >= 0.0 && sunCoverage <= 1.0 && noiseCoverage >= 0.0 && noiseCoverage <= 6.0 &&
          detailWeight >= 0.0 && detailWeight <= 1.0 && all(lessThan(abs(detailCoord), vec2(1e20)))))
        return CloudSample(nativeCoord, wind, cloudGradient, sunCoverage, dither);
    // Detail blue is normalized to [0,1]. Preserve native ordered clear-weather pre-max arithmetic.
    float upper = mix(noiseBase, 1.0, detailWeight) * 21.0;
    upper = upper - noiseCoverage;
    upper = upper - (sunCoverage * 3.0 + CLOUD_AMOUNT);
    if (upper < -0.001) return 0.0;
    float noiseDetail = ShaderLodCloudDetailLod0(detailCoord, cloudGradient);
    return CloudCombineDefault(noiseBase, noiseDetail, noiseCoverage, sunCoverage);
}
#endif

#if SHADERLOD_REFINEMENT_ADAPTER == 1 && defined SHADERLOD_BSL_REFLECTED_CONTEXT && defined OVERWORLD && defined FSH && defined ADVANCED_MATERIALS && defined REFLECTION_SPECULAR && defined REFLECTION_ROUGH && !defined REFLECTION_PREVIOUS && ALPHA_BLEND == 0 && CLOUDS == 2 && CLOUD_BASE == 0 && !defined DISTANT_HORIZONS && !defined VOXY && !defined WORLD_CURVATURE
bool shaderlodBslCloudFinite(float v) { return abs(v) <= 1.0e12; }
bool shaderlodBslCloudFinite3(vec3 v) { return all(lessThanEqual(abs(v),vec3(1.0e12))); }
bool shaderlodBslCloudWholeOutside(vec3 firstPos, vec3 sampleStep, vec3 cameraPos,
                                  int samples, float fadeEnd, float factor) {
    if (samples < 1 || samples > 33 || !shaderlodBslCloudFinite3(firstPos) ||
        !shaderlodBslCloudFinite3(sampleStep) || !shaderlodBslCloudFinite3(cameraPos) ||
        !(fadeEnd > 0.0 && fadeEnd < 1.0e6) || !(factor > 0.0 && factor < 1.0)) return false;
    // Inspect the SAME actual dithered first position and additive native trajectory.
    // This small geometry prepass has no density/noisetex reads. No analytic FP certificate.
    vec3 probe=firstPos;
    float boundaryMargin=max(0.001,fadeEnd*0.0001);
    for (int j=0; j<samples; ++j) {
        if (!shaderlodBslCloudFinite3(probe)) return false;
        vec2 radial=probe.xz-cameraPos.xz;
        float radius=length(radial);
        float outward=dot(radial,sampleStep.xz);
        float outwardMargin=0.0001*max(1.0,radius*length(sampleStep.xz));
        if (!(radius*factor > fadeEnd+boundaryMargin) || !(outward > outwardMargin)) return false;
        probe += sampleStep;
    }
    return true;
}
#endif

float InvLerp(float v, float l, float h) {
	return clamp((v - l) / (h - l), 0.0, 1.0);
}

float GetCloudMask(vec3 viewPos, float z) {
	if (z == 1.0) return 1.0;

	#ifdef FAR_VANILLA_FOG_OVERWORLD
	#if FAR_VANILLA_FOG_STYLE == 0
	float fogFactor = length(viewPos);
	#else
	vec4 worldPos = gbufferModelViewInverse * vec4(viewPos, 1.0);
	worldPos.xyz /= worldPos.w;

	float fogFactor = length(worldPos.xz);
	#endif

	#if MC_VERSION >= 11800
	float fogOffset = 0.0;
	#else
	float fogOffset = 12.0;
	#endif

	float fogFar = far;
	float vanillaDensity = 0.2 * FOG_DENSITY_VANILLA;

	#ifdef VOXY
	fogFar = max(fogFar, vxRenderDistance * 16.0);
	vanillaDensity = 0.4 * sqrt(FOG_DENSITY_VANILLA);
	#endif

	#ifdef DISTANT_HORIZONS
	fogFar = max(fogFar, float(dhRenderDistance));
	vanillaDensity = 0.4 * sqrt(FOG_DENSITY_VANILLA);
	#endif

	float vanillaFog = 1.0 - (fogFar - (fogFactor + fogOffset)) / (vanillaDensity * fogFar);
	vanillaFog = clamp(vanillaFog, 0.0, 1.0);
	
	return vanillaFog;
	#else
	return 0.0;
	#endif
}

vec4 DrawCloudSkybox(vec3 viewPos, float z, float dither, vec3 lightCol, vec3 ambientCol, bool fadeFaster, bool shaderlodReflection) {
	float cloudMask = GetCloudMask(viewPos, z);
	if (cloudMask == 0.0) return vec4(0.0);

	#ifdef TAA
	#if TAA_MODE == 0
	dither = fract(dither + frameCounter * 0.618);
	#else
	dither = fract(dither + frameCounter * 0.5);
	#endif
	#endif

	int samples = CLOUD_THICKNESS * 2;
    float shaderlodCloudRatio = 1.0;
#if (defined SHADERLOD_BSL_PRIMARY_CLOUD_CONTEXT || defined SHADERLOD_BSL_REFLECTED_CONTEXT) && SHADERLOD_REFINEMENT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY
    int shaderlodCloudOriginal = samples;
#ifdef ADVANCED_MATERIALS
    if (shaderlodReflection)
#endif
    samples = shaderlod_bsl_count(samples, 4, length(viewPos),
        shaderlodReflection ? shaderlodOptReflectionCloudBudget : shaderlodOptCloudPrimaryBudget);
    shaderlodCloudRatio = float(shaderlodCloudOriginal) / float(samples);
#endif
	
	float cloud = 0.0, cloudLighting = 0.0;

	float sampleStep = 1.0 / samples;
	float currentStep = dither * sampleStep;
	
	vec3 nViewPos = normalize(viewPos);
	float VoU = dot(nViewPos, upVec);
	float VoL = dot(nViewPos, lightVec);
	
	#ifdef CLOUD_REVEAL
	float sunCoverage = mix(abs(VoL), max(VoL, 0.0), shadowFade);
	sunCoverage = pow(clamp(sunCoverage * 2.0 - 1.0, 0.0, 1.0), 12.0) * (1.0 - rainStrength);
	#else
	float sunCoverage = 0.0;
	#endif

	float convertedHeight = (max(float(CLOUD_HEIGHT), 128.0) - 72.0) / CLOUD_SCALE;

	vec2 wind = vec2(
		time * CLOUD_SPEED * 0.0005,
		sin(time * CLOUD_SPEED * 0.001) * 0.005
	) * 0.667;

	vec3 cloudColor = vec3(0.0);

	if (VoU > 0.025) {
		vec3 wpos = normalize((gbufferModelViewInverse * vec4(viewPos, 1.0)).xyz);

		float halfVoL = mix(abs(VoL) * 0.8, VoL, shadowFade) * 0.5 + 0.5;
		float halfVoLSqr = halfVoL * halfVoL;
		float scattering = pow(halfVoL, 6.0);
		float noiseLightFactor = (2.0 - 1.5 * VoL * shadowFade) * CLOUD_DENSITY * 0.5;

		for(int i = 0; i < samples; i++) {
			if (cloud > 0.99) break;

			#if CLOUD_BASE == 2
			float planeY = convertedHeight + currentStep * CLOUD_THICKNESS * 0.4;
			#else 
			float planeY = convertedHeight + currentStep * CLOUD_THICKNESS;
			#endif

			vec3 planeCoord = wpos * (planeY / wpos.y);
			vec2 cloudCoord = cameraPosition.xz * 0.0625 * 16.0 / CLOUD_SCALE + planeCoord.xz;

#if (defined SHADERLOD_BSL_PRIMARY_CLOUD_CONTEXT || defined SHADERLOD_BSL_REFLECTED_CONTEXT) && CLOUD_BASE == 0 && SHADERLOD_REFINEMENT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY
            float noise = ShaderLodCloudPrimaryClearBound(cloudCoord, wind, currentStep, sunCoverage, dither, shaderlodReflection);
#else
			float noise = CloudSample(cloudCoord, wind, currentStep, sunCoverage, dither);
#endif

			float sampleLighting = pow(currentStep, 1.125 * halfVoLSqr + 0.875) * 0.8 + 0.2;
			sampleLighting *= 1.0 - pow(noise, noiseLightFactor);

            float shaderlodCloudAlpha = noise;
#if (defined SHADERLOD_BSL_PRIMARY_CLOUD_CONTEXT || defined SHADERLOD_BSL_REFLECTED_CONTEXT) && SHADERLOD_REFINEMENT_ADAPTER == 1 && !defined DISTANT_HORIZONS && !defined VOXY
            shaderlodCloudAlpha = shaderlod_bsl_alpha(noise, shaderlodCloudRatio);
#endif
            cloudLighting = mix(cloudLighting, sampleLighting, shaderlodCloudAlpha * (1.0 - cloud * cloud));
			cloud = mix(cloud, 1.0, shaderlodCloudAlpha);

			currentStep += sampleStep;
		}
		cloudLighting = mix(cloudLighting, 1.0, (1.0 - cloud * cloud) * scattering * 0.5);
		cloudLighting *= (1.0 - 0.9 * rainStrength);

		cloudColor = mix(
			ambientCol * (0.3 * sunSkyVisibility + 0.5),
			lightCol * (0.85 + 1.15 * scattering),
			cloudLighting
		);
		cloudColor *= 1.0 - 0.4 * rainStrength;

		cloud *= clamp(1.0 - exp(-16.0 / max(fogDensity, 0.5) * VoU + 0.5), 0.0, 1.0);

		if (fadeFaster) {
			cloud *= 1.0 - pow(1.0 - VoU, 4.0);
		}
	}
	cloudColor *= CLOUD_BRIGHTNESS * (0.5 - 0.25 * (1.0 - sunSkyVisibility) * (1.0 - rainStrength));
	cloudColor *= exp2(mix(mix(SKY_EXPOSURE_N, SKY_EXPOSURE_D, sunSkyVisibility), SKY_EXPOSURE_W, rainStrength));
	
	#ifdef IS_IRIS
	cloudColor *= clamp((cameraPosition.y - bedrockLevel + 6.0) / 8.0, 0.0, 1.0);
	#else
	#if MC_VERSION >= 11800
	cloudColor *= clamp((cameraPosition.y + 70.0) / 8.0, 0.0, 1.0);
	#else
	cloudColor *= clamp((cameraPosition.y + 6.0) / 8.0, 0.0, 1.0);
	#endif
	#endif
	
	#ifdef SKY_UNDERGROUND
	cloud *= mix(clamp((cameraPosition.y - 48.0) / 16.0, 0.0, 1.0), 1.0, eBS);
	#endif
	
	cloud *= cloud;
	cloud *= cloudMask;
	cloud *= CLOUD_OPACITY;
	
	return vec4(cloudColor, cloud);
}

